18	
19	insightsRouter.get('/inbox', async (_req, res) => {
20	  try {
21	    const items = await listInboxItems();
22	    res.json({ items });
23	  } catch (err) {
24	    res.status(500).json({ error: 'Failed to load inbox', detail: String(err) });
