39	insightsRouter.get('/notifications', async (_req, res) => {
40	  try {
41	    // A job-failure alert reminder is already represented by its live
42	    // `task-alert` entry below: one failure, one bell entry.
43	    const items = (await listInboxItems()).filter(
44	      (item) => !(item.kind === 'reminder' && isTaskAlertReminderId(item.itemId)),
45	    );
46	    const conversationNotifs = items.slice(0, 30).map((item) => ({
47	      id: `inbox:${item.projectSlug}:${item.conversationId}:${item.itemId}`,
48	      title: item.itemTitle,
49	      context: item.context ?? item.prompt,
50	      project: {
51	        slug: item.projectSlug,
52	        name: item.projectName,
53	      },
54	      conversationId: item.conversationId,
55	      conversationTitle: item.conversationTitle,
56	      itemId: item.itemId,
57	      href: item.href,
58	      kind: item.kind,
59	      updatedAt: item.conversationUpdatedAt,
60	      sessionIdleSince: item.sessionIdleSince,
61	    }));
62	    // Fils de revue HTML ouverts (Claude a répondu / en attente). Tolérant.
63	    const htmlNotifs = (await listHtmlReviewNotifications().catch(() => [])).slice(0, 30);
64	    // Daemons & jobs launchd actuellement dégradés (taskAlerter.ts) — en tête :
