 * `speechSettings.ts`), pas au localStorage. Se recharge à chaque ouverture
 * du panneau (`open`) pour rester à jour si les réglages ont changé ailleurs.
 */
function SpeechSettingsSection({ open }: { open: boolean }) {
  const { t } = useTranslation();
  const [settings, setSettings] = useState<SpeechSettings | null>(null);
  const [loading, setLoading] = useState(false);
  const [testing, setTesting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Séquencement des sauvegardes (idiome useEditableResource.ts) : seul le
  // DERNIER PUT émis peut appliquer son résultat ou son revert — deux PUT en
  // vol résolus dans le désordre ne doivent pas laisser l'UI sur l'ancien état.
  const saveSeqRef = useRef(0);
  // Dernier état CONFIRMÉ par le serveur (GET ou réponse de PUT) : c'est vers
  // lui qu'un échec revert — jamais vers un instantané optimiste intermédiaire.
  const lastSavedRef = useRef<SpeechSettings | null>(null);

  useEffect(() => {
    if (!open) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    getSpeechSettings()
      .then((next) => {
        if (cancelled) return;
        lastSavedRef.current = next;
        setSettings(next);
      })
      .catch(() => {
        if (!cancelled) setError(t('notifications.speech.loadError'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [open, t]);

  const updateSettings = useCallback(
    async (patch: Partial<SpeechSettings>) => {
      if (!settings) return;
      const optimistic = { ...settings, ...patch };
      const mySeq = ++saveSeqRef.current;
      setSettings(optimistic);
      setError(null);
      try {
        const saved = await saveSpeechSettings(optimistic);
        // Le serveur A persisté cet état : mémoriser même si un PUT plus récent
        // est en vol (un futur revert doit viser un état réellement persisté,
        // jamais un instantané optimiste plus ancien).
        lastSavedRef.current = saved;
        if (mySeq !== saveSeqRef.current) return;
        setSettings(saved);
      } catch {
        if (mySeq !== saveSeqRef.current) return;
        // Revert vers le dernier état CONFIRMÉ serveur — pas vers l'instantané
        // de cette closure, qui peut être l'optimiste d'un PUT précédent.
        setSettings(lastSavedRef.current ?? settings);
        setError(t('notifications.speech.saveError'));
