export function NotificationCenter() {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<NotificationItem[]>([]);
  const navigate = useNavigate();
  const desktop = useDesktopNotifications({
    onNavigate: useCallback((href: string) => navigate(href), [navigate]),
  });
  const notifyRef = useRef(desktop.notify);
  notifyRef.current = desktop.notify;

  /** null tant que le premier fetch n'a pas amorcé le Set → aucune notif au chargement. */
  const seenRef = useRef<Set<string> | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const refresh = useCallback(async () => {
    const nextItems = await getNotifications().catch(() => [] as NotificationItem[]);
    setItems(nextItems);
    return nextItems;
  }, []);

  // Premier chargement : on marque tout l'existant comme vu, sans notifier.
  useEffect(() => {
    void refresh().then((initial) => {
      if (seenRef.current) return;
      const seen = loadSeenIds();
      for (const item of initial) seen.add(item.id);
      seenRef.current = persistSeenIds(seen);
    });
  }, [refresh]);

  const detectNewItems = useCallback(async () => {
    const nextItems = await refresh();
    const seen = seenRef.current;
    if (!seen) return; // l'amorçage initial n'est pas terminé

    const fresh = nextItems.filter((item) => !seen.has(item.id));
    if (fresh.length === 0) return;
    for (const item of fresh) seen.add(item.id);
    seenRef.current = persistSeenIds(seen);

    // Anti-spam : pas de notification si l'onglet est visible ET que
    // l'utilisateur regarde déjà la page de la conversation concernée.
    const notifiable = document.hidden ? fresh : fresh.filter((item) => !isViewing(item.href));
    if (notifiable.length === 0) return;

    const [first] = notifiable;
    notifyRef.current({
      title: t('notifications.newItem', { count: notifiable.length }),
      body:
        notifiable.length === 1
          ? first.title
          : (first.project?.name ?? first.conversationTitle ?? 'Workstation'),
      href: first.href,
      tag: 'workstation-nouveaux-items',
    });
  }, [refresh, t]);

  useServerEvents(
    useCallback(
      (event) => {
        if (
          event.type === 'conversations-changed' ||
          event.type === 'html-review-changed' ||
          event.type === 'task-healthcheck'
        ) {
          // Debounce : le watcher peut émettre en rafale lors d'une écriture.
          // Les revues HTML ouvertes (et les réponses de Claude) entrent dans la
          // même boucle « à traiter » que les conversations. `task-healthcheck`
          // (transition de santé d'un daemon/job launchd, jamais un tick stable)
          // fait apparaître/disparaître les entrées `task-alert` sans attendre.
          if (debounceRef.current) clearTimeout(debounceRef.current);
          debounceRef.current = setTimeout(() => void detectNewItems(), DEBOUNCE_MS);
        } else if (event.type === 'projects-changed') {
          void refresh();
        }
      },
      [detectNewItems, refresh],
    ),
  );

  useEffect(
    () => () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    },
    [],
  );

  const pendingCount = items.length;
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    window.addEventListener('mousedown', onDoc);
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('mousedown', onDoc);
      window.removeEventListener('keydown', onKey);
    };
  }, [open]);

  return (
    <div ref={rootRef} className="relative">
      <button data-shape="icon"
        type="button"
        onClick={() => setOpen((current) => !current)}
        className="glass-control relative inline-flex h-8 w-8 items-center justify-center rounded-lg border border-line bg-paper-raised text-ink-soft shadow-warm-sm transition-all hover:border-accent/50 hover:text-accent active:scale-95"
        aria-label={t('notifications.openNotifications')}
        title={t('notifications.title')}
      >
        <Bell className="h-4 w-4" aria-hidden />
        {pendingCount > 0 && (
          <span className="absolute -right-1 -top-1 min-w-4 rounded-full bg-accent px-1 text-center font-mono text-[0.625rem] leading-4 text-paper-raised">
            {pendingCount > 9 ? '9+' : pendingCount}
          </span>
        )}
      </button>

      {open && (
        <>
          {/* Backdrop mobile pour fermer facilement au toucher */}
          <div
            className="fixed inset-0 z-40 bg-ink/20 backdrop-blur-xs sm:hidden"
            onClick={() => setOpen(false)}
            aria-hidden
          />
          <div className="glass-popover fixed inset-x-3 top-14 z-50 overflow-hidden rounded-lg border border-line bg-paper-raised shadow-lift sm:absolute sm:inset-x-auto sm:right-0 sm:top-10 sm:w-[22rem]">
            <div className="border-b border-line px-4 py-3">
              <p className="eyebrow text-accent">{t('notifications.title')}</p>
              <p className="mt-1 text-sm text-ink-soft">
                {pendingCount === 0 ? t('notifications.nothingPending') : t('notifications.pendingCount', { count: pendingCount })}
              </p>
            </div>

            <div className="max-h-80 overflow-y-auto p-2">
              {items.length === 0 ? (
                <p className="px-3 py-5 text-sm text-ink-faint">{t('notifications.noLocalAction')}</p>
              ) : (
                items.map((item) => (
                  <Link
                    key={item.id}
                    viewTransition
                    to={item.href}
                    onClick={() => setOpen(false)}
                    className="glass-menu-item block rounded-md px-3 py-2.5 transition-colors hover:bg-paper-deep"
                  >
                    {item.sessionIdleSince && (
                      <span className="eyebrow mb-0.5 block text-accent-deep">
                        {t('origin.sessionEndedEyebrow', { time: formatRelative(item.sessionIdleSince) })}
                      </span>
