test('flapping : pas de second rappel ni push tant que le premier est pending', async () => {
  await createTask('job-b');
  await setHealth('job-b', false);
  await setHealth('job-b', true);
  await setHealth('job-b', false);
  await setHealth('job-b', true);
  await setHealth('job-b', false);
  await alerter.runTaskAlertSweep();

  expect(await alertReminders('job-b')).toHaveLength(1);
  expect(pushBodies()).toHaveLength(1);
});

test('rappel marqué fait : pas de ré-alerte tant que l’échec dure, ré-alerte au prochain échec', async () => {
  await createTask('job-c');
  await setHealth('job-c', false);
  const [first] = await alertReminders('job-c');
  await markDone(first.id);

  // Toujours en échec (même épisode) : aucun nouveau rappel.
  await setHealth('job-c', false);
  await alerter.runTaskAlertSweep();
  expect((await alertReminders('job-c')).filter((r) => r.status === 'pending')).toHaveLength(0);
  expect(pushBodies()).toHaveLength(1);

  // Rétabli puis nouvel échec : nouvelle alerte.
  await setHealth('job-c', true);
  await setHealth('job-c', false);
  const all = await alertReminders('job-c');
  expect(all).toHaveLength(2);
  expect(all.filter((r) => r.status === 'pending')).toHaveLength(1);
  expect(pushBodies()).toHaveLength(2);
});

