74	function priorityFlag(args: string[]): ItemPriority | undefined {
75	  const raw = flagValue(args, '--priority');
76	  if (raw === undefined) return undefined;
77	  const parsed = ItemPrioritySchema.safeParse(raw.toLowerCase());
78	  if (!parsed.success) fail(`--priority doit valoir low, normal, high ou urgent (reçu "${raw}")`);
79	  return parsed.data;
80	}
