86	async function cmdAdd(rest: string[]) {
87	  const positionals = rest.filter((a, i) => !a.startsWith('--') && !(i > 0 && rest[i - 1]?.startsWith('--')));
88	  const [text] = positionals;
89	  if (!text || !text.trim()) {
90	    fail(`usage: ${USAGE.add}`);
91	  }
92	
93	  const due = flagValue(rest, '--due');
94	  if (due !== undefined && Number.isNaN(Date.parse(due))) {
95	    fail(`--due n'est pas une date ISO valide : "${due}"`);
96	  }
97	  const project = flagValue(rest, '--project');
98	  const priority = priorityFlag(rest);
99	
100	  const conversation = await loadOrInitRemindersConversation();
101	  const isNew = conversation.items.length === 0 && conversation.updatedAt === conversation.createdAt;
102	
103	  // Origine résolue comme tout autre chemin de création CLI (chantier
104	  // « provenance de session », lot 7) — `buildReminderItem` est le
105	  // constructeur PARTAGÉ avec le chemin MCP (`remind_add`), origin exceptée.
106	  const origin = resolveAgentOrigin({
107	    env: process.env,
108	    cwd: process.cwd(),
109	    source: 'cli',
110	    git: readGitBranch,
111	  });
112	  const item: ReminderItem = buildReminderItem({ text, dueAt: due, priority, project }, origin);
113	
114	  const nextConversation: Conversation = {
115	    ...conversation,
116	    items: [...conversation.items, item],
117	  };
118	
119	  // Garde-fou d'identité (chemin agent) : vérifié UNIQUEMENT sur le nouvel item
120	  // — jamais sur l'historique de la conversation évergreen. `_reminders`
121	  // accumule des rappels déjà traités par l'humain (kind `reminder`,
122	  // response.done, top-level answeredAt) ; rejouer le garde-fou sur le corps
123	  // ENTIER bloquerait à tort tout ajout après le premier rappel complété
124	  // (l'historique porte des réponses légitimes, pas cet ajout). Le nouvel item
125	  // seul n'a jamais de `response` → toujours accepté ici, mais on rejoue le
126	  // MÊME contrôle que `convo create` par discipline (défense en profondeur).
127	  const guard = checkConversationWrite({ items: [item] }, 'claude');
128	  if (!guard.allowed) fail(guard.reason);
129	
130	  const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, nextConversation);
131	  if (!result.ok) {
132	    if ('secretBlocked' in result) {
133	      fail(
134	        `store refused the write — high-confidence secret shape(s) detected ` +
135	          `(${result.patterns.join(', ')}). Un rappel ne doit jamais contenir de valeur de secret.`,
136	      );
137	    }
138	    fail(`store rejected the write — ${saveFailureReason(result)}`);
139	  }
140	
141	  const written = result.conversation.items.find(
142	    (it): it is ReminderItem => it.kind === 'reminder' && it.id === item.id,
143	  ) ?? item;
144	  process.stdout.write(
145	    `VERDICT: ${isNew ? 'CREATED' : 'ADDED'}\n` +
146	      `Path: ${path.join(dataDir(), REMINDERS_SLUG, `${REMINDERS_ID}.json`)}\n` +
147	      `Reminder: ${written.id}\n` +
148	      `Origin: ${written.origin?.runtime ?? 'unknown'} ${written.origin?.sessionId ?? '-'} (${written.origin?.capturedBy ?? 'none'})\n` +
149	      `Texte: ${text.trim()}\n` +
150	      (priority ? `Priorité: ${priority}\n` : '') +
151	      (due ? `Échéance: ${new Date(due).toISOString()}\n` : '') +
152	      `Next: visible en tête du tableau de bord workstation (section « 00 — Rappels »).\n`,
153	  );
154	}
