1	/**
2	 * Whether a SINGLE item, taken in isolation, is EXACTLY a reminder
3	 * `pending → answered` flip and nothing else. Factored out of
4	 * `isReminderDoneOnlyFlip` so each clause below is independently testable and
5	 * — per the lesson baked into this module's doctrine (a guard of the shape
6	 * `if (kind === X && optionalField)` is fail-OPEN the moment the optional
7	 * field is absent) — every check is written as an explicit STRICT equality
8	 * against the exact expected value, never an existence/truthiness check that
9	 * a missing field could silently satisfy.
10	 */
11	function isSingleReminderDoneFlip(prevItem: unknown, nextItem: unknown): boolean {
12	  if (
13	    prevItem === null ||
14	    nextItem === null ||
15	    typeof prevItem !== 'object' ||
16	    typeof nextItem !== 'object'
17	  ) {
18	    return false;
19	  }
20	  const p = prevItem as Record<string, unknown>;
21	  const n = nextItem as Record<string, unknown>;
22	
23	  // `kind` must be the literal 'reminder' on BOTH sides. Fail-closed: a
24	  // missing/undefined `kind`, or any value other than the exact literal,
25	  // rejects — there is no code path here where absence reads as a pass.
26	  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
27	
28	  // `status` must flip EXACTLY 'pending' -> 'answered'. Any other pair
29	  // (unchanged, or a transition to/from anything else) is rejected.
30	  if (p.status !== 'pending' || n.status !== 'answered') return false;
31	
32	  // The previous item must not already carry a response — a done flip
33	  // originates from a genuinely pending reminder, never re-answers one.
34	  if (p.response !== undefined && p.response !== null) return false;
35	
36	  // `response` on the next item must be STRICTLY `{ done: true }` — exactly
37	  // one key, that key named `done`, that value `true`. An extra field, a
38	  // missing field, or `done: false` all reject.
39	  if (n.response === null || typeof n.response !== 'object' || Array.isArray(n.response)) {
40	    return false;
41	  }
42	  const responseKeys = Object.keys(n.response as Record<string, unknown>);
43	  if (responseKeys.length !== 1 || responseKeys[0] !== 'done') return false;
44	  if ((n.response as Record<string, unknown>).done !== true) return false;
45	
46	  // `answeredAt` must be newly ADDED by this flip: absent (or null) before,
47	  // a syntactically valid ISO datetime string after.
48	  if (p.answeredAt !== undefined && p.answeredAt !== null) return false;
49	  if (typeof n.answeredAt !== 'string' || Number.isNaN(Date.parse(n.answeredAt))) return false;
50	
51	  // Every other field on the item (id, kind, title, prompt, context, body,
52	  // dueAt, priority, comment, …) must be byte-identical — this flip touches
53	  // ONLY status/response/answeredAt.
54	  const pClone = { ...p };
55	  const nClone = { ...n };
56	  delete pClone.status;
57	  delete nClone.status;
58	  delete pClone.response;
59	  delete nClone.response;
60	  delete pClone.answeredAt;
61	  delete nClone.answeredAt;
62	  return JSON.stringify(pClone) === JSON.stringify(nClone);
63	}
64	
65	/**
66	 * The reminder-`done` counterpart of `isHandledOnlyFlip`: whether `next` is
67	 * `previous` with EXACTLY ONE `kind: 'reminder'` item flipped from
68	 * `pending` to `answered` (see `isSingleReminderDoneFlip` for the per-item
69	 * clauses) and nothing else in the conversation touched. Wired into
70	 * `remind done` (`server/cli/remind.ts`) as the write-path gate — the agent
71	 * CLI path is allowed to author exactly this one mutation on its own
72	 * evergreen `_reminders` conversation, and nothing broader.
73	 *
74	 * FAIL-CLOSED by construction: any shape that doesn't parse as
75	 * `{ items: [...] }` on both sides, any count of changed items other than
76	 * exactly one, or a changed item that isn't precisely the flip described
77	 * above, returns `false`. There is no path where malformed or unexpected
78	 * input is waved through.
79	 */
80	export function isReminderDoneOnlyFlip(previous: unknown, next: unknown): boolean {
81	  if (
82	    previous === null ||
83	    next === null ||
84	    typeof previous !== 'object' ||
85	    typeof next !== 'object'
86	  ) {
87	    return false;
88	  }
89	  const p = previous as Record<string, unknown>;
90	  const n = next as Record<string, unknown>;
91	
92	  const pItems = Array.isArray(p.items) ? p.items : null;
93	  const nItems = Array.isArray(n.items) ? n.items : null;
94	  if (!pItems || !nItems || pItems.length !== nItems.length) return false;
95	
96	  let changedIndex = -1;
97	  for (let i = 0; i < pItems.length; i++) {
98	    if (JSON.stringify(pItems[i]) === JSON.stringify(nItems[i])) continue;
99	    // A SECOND changed item means this is not a single-item flip — reject.
100	    if (changedIndex !== -1) return false;
101	    changedIndex = i;
102	  }
103	  // No item changed at all is not a done flip either.
104	  if (changedIndex === -1) return false;
105	  if (!isSingleReminderDoneFlip(pItems[changedIndex], nItems[changedIndex])) return false;
106	
107	  // Everything OTHER than `items` must stay byte-identical, except
108	  // `updatedAt` — the store stamps that mechanically on every save, exactly
109	  // like `isHandledOnlyFlip` exempts it above.
110	  const pClone = { ...p };
111	  const nClone = { ...n };
112	  delete pClone.items;
113	  delete nClone.items;
114	  delete pClone.updatedAt;
115	  delete nClone.updatedAt;
116	  return JSON.stringify(pClone) === JSON.stringify(nClone);
117	}
118	
119	/**
120	 * Whether a SINGLE `kind: 'reminder'` item, taken in isolation, differs from
121	 * its previous version in ONLY its `origin` field — same STRICT-equality
122	 * discipline as `isSingleReminderDoneFlip`. `status`/`response`/`answeredAt`
123	 * and every other field must be byte-identical; only `origin` may differ (in
124	 * EITHER direction — absent -> present, or one origin value -> another —
125	 * `stampReminderOrigin`'s own `mergeOrigin` call already decided what the new
126	 * value should be, this guard only certifies that origin is the ONLY thing
127	 * that moved).
128	 */
129	function isSingleReminderOriginFlip(prevItem: unknown, nextItem: unknown): boolean {
130	  if (
131	    prevItem === null ||
132	    nextItem === null ||
133	    typeof prevItem !== 'object' ||
134	    typeof nextItem !== 'object'
135	  ) {
136	    return false;
137	  }
138	  const p = prevItem as Record<string, unknown>;
139	  const n = nextItem as Record<string, unknown>;
140	
141	  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
142	  if (p.id !== n.id || typeof p.id !== 'string') return false;
143	
144	  const pClone = { ...p };
145	  const nClone = { ...n };
146	  delete pClone.origin;
147	  delete nClone.origin;
148	  return JSON.stringify(pClone) === JSON.stringify(nClone);
149	}
150	
151	/**
152	 * The origin-stamping counterpart of `isReminderDoneOnlyFlip`: whether
153	 * `next` is `previous` with EXACTLY ONE `kind: 'reminder'` item's `origin`
154	 * field changed and nothing else in the conversation touched (see
155	 * `isSingleReminderOriginFlip` for the per-item clause). Wired into
156	 * `stampReminderOrigin` (`server/services/reminderStore.ts`) — defense in
157	 * depth for a write path that only ever intends to touch one item's
158	 * `origin`, never `response`/`status`/`items` count.
159	 *
160	 * FAIL-CLOSED by construction, identical shape to `isReminderDoneOnlyFlip`.
161	 */
162	export function isReminderOriginOnlyFlip(previous: unknown, next: unknown): boolean {
163	  if (
164	    previous === null ||
165	    next === null ||
166	    typeof previous !== 'object' ||
167	    typeof next !== 'object'
168	  ) {
169	    return false;
170	  }
171	  const p = previous as Record<string, unknown>;
172	  const n = next as Record<string, unknown>;
173	
174	  const pItems = Array.isArray(p.items) ? p.items : null;
175	  const nItems = Array.isArray(n.items) ? n.items : null;
176	  if (!pItems || !nItems || pItems.length !== nItems.length) return false;
177	
178	  let changedIndex = -1;
179	  for (let i = 0; i < pItems.length; i++) {
180	    if (JSON.stringify(pItems[i]) === JSON.stringify(nItems[i])) continue;
181	    if (changedIndex !== -1) return false;
182	    changedIndex = i;
183	  }
184	  if (changedIndex === -1) return false;
185	  if (!isSingleReminderOriginFlip(pItems[changedIndex], nItems[changedIndex])) return false;
186	
187	  const pClone = { ...p };
188	  const nClone = { ...n };
189	  delete pClone.items;
190	  delete nClone.items;
191	  delete pClone.updatedAt;
192	  delete nClone.updatedAt;
193	  return JSON.stringify(pClone) === JSON.stringify(nClone);
194	}
195	
196	/** Fields an agent-driven reminder EDIT (`remind update`, MCP `remind_update`) may change. */
197	const REMINDER_EDITABLE_FIELDS = ['body', 'prompt', 'dueAt', 'priority', 'status', 'response', 'answeredAt'] as const;
198	const REMINDER_PRIORITIES = ['low', 'normal', 'high', 'urgent'];
199	
200	/**
201	 * Whether a SINGLE `kind: 'reminder'` item differs from its previous version
202	 * ONLY by an edit an agent is allowed to author: text (`body`+`prompt`),
203	 * `dueAt` (set, changed or cleared), `priority`, and the done/reopen
204	 * transition. Same STRICT-equality discipline as `isSingleReminderDoneFlip`:
205	 * every field outside `REMINDER_EDITABLE_FIELDS` must be byte-identical, and
206	 * the status fields may only land on one of the two exact shapes `remind
207	 * done` / a restore produce — never an arbitrary `response`.
208	 */
209	function isSingleReminderEdit(prevItem: unknown, nextItem: unknown): boolean {
210	  if (
211	    prevItem === null ||
212	    nextItem === null ||
213	    typeof prevItem !== 'object' ||
214	    typeof nextItem !== 'object'
215	  ) {
216	    return false;
217	  }
218	  const p = prevItem as Record<string, unknown>;
219	  const n = nextItem as Record<string, unknown>;
220	
221	  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
222	  if (p.id !== n.id || typeof p.id !== 'string') return false;
223	
224	  // Text: `body` stays a non-empty string (`prompt` is rewritten alongside it by `applyReminderPatch`).
225	  if (typeof n.body !== 'string' || n.body.trim() === '' || typeof n.prompt !== 'string') return false;
226	  // dueAt: absent or a parseable ISO datetime.
227	  if (n.dueAt !== undefined && (typeof n.dueAt !== 'string' || Number.isNaN(Date.parse(n.dueAt)))) return false;
228	  // priority: absent or one of the schema's literals.
229	  if (n.priority !== undefined && !REMINDER_PRIORITIES.includes(n.priority as string)) return false;
230	
231	  // Status: exactly the two shapes `remind done` and a restore produce.
232	  if (n.status === 'answered') {
233	    if (n.response === null || typeof n.response !== 'object' || Array.isArray(n.response)) return false;
234	    const keys = Object.keys(n.response as Record<string, unknown>);
235	    if (keys.length !== 1 || keys[0] !== 'done' || (n.response as Record<string, unknown>).done !== true) return false;
236	    if (typeof n.answeredAt !== 'string' || Number.isNaN(Date.parse(n.answeredAt))) return false;
237	    // An already-answered reminder keeps its original answer timestamp.
238	    if (p.status === 'answered' && n.answeredAt !== p.answeredAt) return false;
239	  } else if (n.status === 'pending') {
240	    if (n.response !== undefined || n.answeredAt !== undefined) return false;
241	  } else {
242	    return false;
243	  }
244	
245	  const pClone = { ...p };
246	  const nClone = { ...n };
247	  for (const field of REMINDER_EDITABLE_FIELDS) {
248	    delete pClone[field];
249	    delete nClone[field];
250	  }
251	  return JSON.stringify(pClone) === JSON.stringify(nClone);
252	}
253	
254	/**
255	 * The edit counterpart of `isReminderDoneOnlyFlip`: whether `next` is
256	 * `previous` with EXACTLY ONE `kind: 'reminder'` item edited (see
257	 * `isSingleReminderEdit`) and nothing else in the conversation touched.
258	 * Wired into `updateReminder` (`server/services/reminderStore.ts`), the
259	 * shared write path of `remind update` and the MCP `remind_update` tool.
260	 * FAIL-CLOSED by construction, identical shape to `isReminderDoneOnlyFlip`.
261	 */
262	export function isReminderEditOnlyFlip(previous: unknown, next: unknown): boolean {
263	  if (
264	    previous === null ||
265	    next === null ||
266	    typeof previous !== 'object' ||
267	    typeof next !== 'object'
268	  ) {
269	    return false;
270	  }
271	  const p = previous as Record<string, unknown>;
272	  const n = next as Record<string, unknown>;
273	
274	  const pItems = Array.isArray(p.items) ? p.items : null;
275	  const nItems = Array.isArray(n.items) ? n.items : null;
276	  if (!pItems || !nItems || pItems.length !== nItems.length) return false;
277	
278	  let changedIndex = -1;
279	  for (let i = 0; i < pItems.length; i++) {
280	    if (JSON.stringify(pItems[i]) === JSON.stringify(nItems[i])) continue;
281	    if (changedIndex !== -1) return false;
282	    changedIndex = i;
283	  }
284	  if (changedIndex === -1) return false;
285	  if (!isSingleReminderEdit(pItems[changedIndex], nItems[changedIndex])) return false;
286	
287	  const pClone = { ...p };
288	  const nClone = { ...n };
289	  delete pClone.items;
290	  delete nClone.items;
291	  delete pClone.updatedAt;
292	  delete nClone.updatedAt;
293	  return JSON.stringify(pClone) === JSON.stringify(nClone);
294	}
